//! The full API contract, generated by the native build.
//!
//! A build without Native Parts serves the same contract. It reads the
//! checked-in contract instead of building descriptions from handlers
//! whose services are absent.

pub struct ApiDoc;

impl ApiDoc {
    pub fn openapi() -> serde_json::Value {
        serde_json::from_str(include_str!("../../../ui/openapi.json"))
            .expect("the generated API contract is valid")
    }

    pub fn to_pretty_json() -> String {
        include_str!("../../../ui/openapi.json")
            .trim_end()
            .to_string()
    }
}
